const app=window.Telegram?.WebApp, form=document.querySelector('#registrationProfile'),status=document.querySelector('#status');
app?.ready();app?.expand();
const headers={'X-Telegram-Init-Data':app?.initData||'','Content-Type':'application/json'};
async function load(){try{const response=await fetch('/api/me',{headers});const user=await response.json();if(!response.ok)throw Error(user.error);form.hidden=false;document.querySelector('#greeting').textContent='Приветствуем, '+user.fullName+' 👋';document.querySelector('#roleName').textContent={coach:'Тренер',player:'Игрок',parent:'Родитель'}[user.role];form.elements.fullName.value=user.fullName;form.elements.city.value=user.city;form.elements.venue.value=user.customVenue||[user.venue,user.address].filter(Boolean).join(' · ')||'Пока не указан';form.elements.bio.value=user.bio||'';status.textContent='';}catch(error){status.textContent=error.message||'Не удалось загрузить профиль';}}
form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const response=await fetch('/api/me',{method:'POST',headers,body:JSON.stringify({fullName:form.elements.fullName.value,bio:form.elements.bio.value})});if(!response.ok)throw Error('Не удалось сохранить. Откройте приложение заново из бота.');status.textContent='✅ Профиль сохранён';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};
load();
